-- M78 additive bounded synthetic process discovery and gross Scope 1 workpapers.
-- Existing source methods, results, corporate graphs and migration bytes are retained.
create table neuvetra.scope1_heads(id uuid primary key,company_id uuid not null references neuvetra.companies(id),family text not null check(family in('process_screen','inventory')),year integer not null default 2025 check(year=2025),version_id uuid,revision integer not null default 0,unique(id,company_id),unique(company_id,family,year));
create table neuvetra.scope1_statements(id uuid primary key,company_id uuid not null references neuvetra.companies(id),payload jsonb not null,statement_sha256 text not null,statement_text text not null,unique(id,company_id));
create table neuvetra.scope1_versions(id uuid primary key,company_id uuid not null,stream_id uuid not null,family text not null check(family in('process_screen','inventory')),version integer not null,previous_version_id uuid,coverage_version_id uuid not null,payload jsonb not null,proof jsonb not null,input_sha256 text not null,content_sha256 text not null,version_sha256 text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null,export_text text not null,unique(id,company_id),unique(company_id,stream_id,version),foreign key(stream_id,company_id)references neuvetra.scope1_heads(id,company_id),foreign key(previous_version_id,company_id)references neuvetra.scope1_versions(id,company_id),foreign key(coverage_version_id,company_id)references neuvetra.corporate_inventory_versions(id,company_id));
alter table neuvetra.scope1_heads add foreign key(version_id,company_id)references neuvetra.scope1_versions(id,company_id);
create table neuvetra.scope1_reviews(id uuid primary key,company_id uuid not null,version_id uuid not null,payload jsonb not null,decision_sha256 text not null,reviewed_by uuid not null references auth.users(id),reviewed_at timestamptz not null,unique(id,company_id),unique(company_id,version_id),foreign key(version_id,company_id)references neuvetra.scope1_versions(id,company_id));
create table neuvetra.scope1_reports(id uuid primary key,company_id uuid not null,stream_id uuid not null,family text not null check(family in('process_screen','inventory')),version_id uuid not null,payload jsonb not null,report_sha256 text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null,unique(id,company_id),foreign key(stream_id,company_id)references neuvetra.scope1_heads(id,company_id),foreign key(version_id,company_id)references neuvetra.scope1_versions(id,company_id));
create table neuvetra.scope1_requests(company_id uuid not null references neuvetra.companies(id),idempotency_key uuid not null,actor_id uuid not null references auth.users(id),kind text not null check(kind in('save','review','report')),family text not null check(family in('process_screen','inventory')),stream_id uuid,fingerprint text not null,record_id uuid not null,primary key(company_id,idempotency_key));
create table neuvetra.scope1_audit(sequence bigserial primary key,id uuid not null unique,company_id uuid not null references neuvetra.companies(id),record_id uuid not null,kind text not null check(kind in('save','review','report')),record_sha256 text not null,actor_id uuid not null references auth.users(id),created_at timestamptz not null,unique(company_id,kind,record_id));
create table neuvetra.scope1_process_discoveries(company_id uuid not null,year integer not null default 2025 check(year=2025),discovery_key text not null,stream_id uuid not null,created_at timestamptz not null,primary key(company_id,year,discovery_key),foreign key(stream_id,company_id)references neuvetra.scope1_heads(id,company_id));
do $$declare t text;begin foreach t in array array['scope1_heads','scope1_statements','scope1_versions','scope1_reviews','scope1_reports','scope1_requests','scope1_audit','scope1_process_discoveries']loop execute format('alter table neuvetra.%I enable row level security',t);execute format('alter table neuvetra.%I force row level security',t);execute format('revoke all on neuvetra.%I from public,authenticated,neuvetra_runtime',t);execute format('create policy m78_read on neuvetra.%I for select to neuvetra_runtime using(neuvetra.has_staging_access() and neuvetra.is_company_member(company_id))',t);execute format('grant select on neuvetra.%I to neuvetra_runtime',t);if t<>'scope1_heads'then execute format('create trigger m78_immutable before update or delete on neuvetra.%I for each row execute function neuvetra.reject_inventory_history_mutation()',t);end if;end loop;end $$;
revoke all on sequence neuvetra.scope1_audit_sequence_seq from public,authenticated,neuvetra_runtime;

-- Reviewed existing INVOKER literal/RAISE bodies: configuration-only hardening.
alter function neuvetra.electricity_source_fixtures() set search_path=pg_catalog,pg_temp;
alter function neuvetra.reject_inventory_history_mutation() set search_path=pg_catalog,pg_temp;
alter function neuvetra.m67_method() set search_path=pg_catalog,pg_temp;
alter function neuvetra.m67_limitations() set search_path=pg_catalog,pg_temp;
alter function neuvetra.m68_limitations() set search_path=pg_catalog,pg_temp;
alter function neuvetra.annual_evidence_report_template() set search_path=pg_catalog,pg_temp;

create function neuvetra.m78_lock(target_company uuid,writing boolean)returns boolean language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$begin if not neuvetra.m71_lock(target_company,writing)then return false;end if;if writing then perform id from neuvetra.companies where id=target_company for update;perform id from neuvetra.scope1_heads where company_id=target_company order by id for update;else perform id from neuvetra.companies where id=target_company for share;end if;return true;end $$;
create function neuvetra.m78_pin(v jsonb,review boolean default false)returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select case when v is null or v='null'::jsonb then 'null'::jsonb else jsonb_build_object('id',v->'id','sha256',v->case when review then 'decisionSha256'else 'versionSha256'end)end$$;
create function neuvetra.m78_finding(code text,message text,record_id text default null,family text default 'm78',classification text default 'functional_blocker',resolution jsonb default null)returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select jsonb_build_object('code',code,'origin',jsonb_build_object('family',family,'recordId',record_id,'originalCode',code),'classification',classification,'message',message,'resolution',resolution)$$;
create function neuvetra.m78_limitations()returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select '["synthetic_only","scope1_incomplete","corporate_inventory_incomplete","factor_and_method_not_released","requirements_not_determined","no_external_assurance"]'::jsonb$$;
create function neuvetra.m78_physical(p jsonb,family text,v jsonb)returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select case family when 'fugitive'then v#>'{activity,assetId}' when 'mobile_diesel'then v#>'{activity,vehicle,assetId}'when 'stationary_diesel'then v#>'{activity,equipment,assetId}'else coalesce((select r->'equipmentId'from jsonb_array_elements(p#>'{stationary,reconciliation,rows}')r where r->'sourceId'=v#>'{activity,binding,sourceId}'limit 1),'null'::jsonb)end$$;
create function neuvetra.m78_dependencies(p jsonb,family text)returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$with body as(select jsonb_build_object('coveragePin',neuvetra.m78_pin(p->'coverageVersion'),'coverageReviewPin',neuvetra.m78_pin(p#>'{coverageVersion,review}',true),'processVersionPin',case when family='inventory'then neuvetra.m78_pin(p#>'{process,version}')else 'null'::jsonb end,'processReviewPin',case when family='inventory'then neuvetra.m78_pin(p#>'{process,review}',true)else 'null'::jsonb end,'sourcePins',coalesce((select jsonb_agg(jsonb_build_object('family',x->'family','worksheetId',coalesce(x#>'{version,worksheetId}',x#>'{version,streamId}'),'sourceId',x#>'{version,activity,binding,sourceId}','physicalId',neuvetra.m78_physical(p,x->>'family',x->'version'),'version',neuvetra.m78_pin(x->'version'),'decision',neuvetra.m78_pin(x#>'{version,review}',true))order by coalesce(x#>>'{version,worksheetId}',x#>>'{version,streamId}')collate "C")from jsonb_array_elements(p->'sourceVersions')x),'[]'::jsonb),'discoveryPins',(select jsonb_agg(jsonb_build_object('family',k,'version',neuvetra.m78_pin(p#>array[k,'version']),'decision',neuvetra.m78_pin(p#>array[k,'review'],true),'dependencySha256',p#>array[k,'reconciliation','dependencySha256'],'reconciliationSha256',p#>array[k,'reconciliation','contentSha256'])order by n)from unnest(array['fleet','stationary','fugitive'])with ordinality q(k,n)),'policySha256',case when family='inventory'then coalesce(p#>'{policy,policySha256}','null'::jsonb)else 'null'::jsonb end,'rulesVersion','m78-gross-scope1-v1')b)select b||jsonb_build_object('dependencySha256',neuvetra.m67_hash(b))from body$$;
create function neuvetra.m78_contributors(p jsonb,prior jsonb,actor uuid,family text)returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select jsonb_agg(to_jsonb(k)order by k collate "C")from(select distinct k from(select x#>>'{}'k from jsonb_array_elements(coalesce(prior->'contributorIds','[]'::jsonb))x union all select x#>>'{}'from jsonb_array_elements(p#>'{coverageVersion,contributorIds}')x union all select x#>>'{}'from jsonb_array_elements(p->'sourceVersions')v,jsonb_array_elements(v#>'{version,contributorIds}')x union all select x#>>'{}'from unnest(array['fleet','stationary','fugitive'])d,jsonb_array_elements(coalesce(p#>array[d,'version','contributorIds'],'[]'::jsonb))x union all select x#>>'{}'from jsonb_array_elements(case when family='inventory'then coalesce(p#>'{process,version,contributorIds}','[]'::jsonb)else '[]'::jsonb end)x union all select actor::text)q)r$$;

-- Current exact retained heads, reviews and independent reconciliation authority.
create function neuvetra.m78_assert_current_proof(target_company uuid,p jsonb,check_process boolean default true)returns void language plpgsql stable security definer set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare x jsonb;actual jsonb;expected jsonb;d text;v jsonb;r jsonb;deps jsonb;bound jsonb;begin
perform neuvetra.m71_keys(p,'priorVersions,coverageVersion,boundCoverageVersions,sourceVersions,fleet,stationary,fugitive,process,policy');if p->'coverageVersion'is distinct from neuvetra.m77_current_coverage(target_company)then raise exception 'current corporate proof changed'using errcode='23505';end if;
select coalesce(jsonb_agg(x order by x#>>'{version,id}'collate "C"),'[]')into expected from(
select jsonb_build_object('family','natural_gas','version',v.payload||jsonb_build_object('review',r.payload))x from neuvetra.stationary_gas_heads h join neuvetra.stationary_gas_versions v on v.id=h.version_id and v.company_id=h.company_id left join neuvetra.stationary_gas_reviews r on r.version_id=v.id and r.company_id=v.company_id where h.company_id=target_company
union all select jsonb_build_object('family','mobile_diesel','version',v.payload||jsonb_build_object('review',r.payload))from neuvetra.mobile_diesel_heads h join neuvetra.mobile_diesel_versions v on v.id=h.version_id and v.company_id=h.company_id left join neuvetra.mobile_diesel_reviews r on r.version_id=v.id and r.company_id=v.company_id where h.company_id=target_company
union all select jsonb_build_object('family','stationary_diesel','version',v.payload||jsonb_build_object('review',r.payload))from neuvetra.stationary_diesel_heads h join neuvetra.stationary_diesel_versions v on v.id=h.version_id and v.company_id=h.company_id left join neuvetra.stationary_diesel_reviews r on r.version_id=v.id and r.company_id=v.company_id where h.company_id=target_company
union all select jsonb_build_object('family','fugitive','version',v.payload||jsonb_build_object('review',r.payload))from neuvetra.fugitive_heads h join neuvetra.fugitive_versions v on v.id=h.version_id and v.company_id=h.company_id left join neuvetra.fugitive_reviews r on r.version_id=v.id and r.company_id=v.company_id where h.company_id=target_company and h.family='source')q;
if p->'sourceVersions'is distinct from expected then raise exception 'current source proof changed'using errcode='23505';end if;
foreach d in array array['fleet','stationary','fugitive']loop
 if d='fleet'then select v.payload into v from neuvetra.controlled_fleet_heads h join neuvetra.controlled_fleet_versions v on v.id=h.version_id and v.company_id=h.company_id where h.company_id=target_company;actual:=neuvetra.m75_current_reconciliation(target_company);select rr.payload into r from neuvetra.controlled_fleet_reviews rr where rr.company_id=target_company and rr.version_id=(v->>'id')::uuid and rr.payload#>>'{dependencies,dependencySha256}'=actual->>'dependencySha256';
 elsif d='stationary'then select v.payload into v from neuvetra.stationary_equipment_heads h join neuvetra.stationary_equipment_versions v on v.id=h.version_id and v.company_id=h.company_id where h.company_id=target_company;actual:=neuvetra.m76_current_reconciliation(target_company);select rr.payload into r from neuvetra.stationary_equipment_reviews rr where rr.company_id=target_company and rr.version_id=(v->>'id')::uuid and rr.payload#>>'{dependencies,dependencySha256}'=actual->>'dependencySha256';
 else select vv.payload into v from neuvetra.fugitive_heads h join neuvetra.fugitive_versions vv on vv.id=h.version_id and vv.company_id=h.company_id where h.company_id=target_company and h.family='population';deps:=neuvetra.m77_current_dependencies(target_company);select rr.payload into r from neuvetra.fugitive_reviews rr where rr.company_id=target_company and rr.version_id=(v->>'id')::uuid and rr.payload#>>'{dependencies,dependencySha256}'=deps->>'dependencySha256';actual:=neuvetra.m77_reconciliation(target_company,p->'coverageVersion',neuvetra.m77_current_workpapers(target_company),v,r);end if;
 if p->d is distinct from jsonb_build_object('version',v,'review',r,'reconciliation',actual)then raise exception 'current discovery proof changed'using errcode='23505';end if;
end loop;
select jsonb_build_object('version',vv.payload,'review',rr.payload,'proof',vv.proof)into actual from neuvetra.scope1_heads h join neuvetra.scope1_versions vv on vv.id=h.version_id and vv.company_id=h.company_id left join neuvetra.scope1_reviews rr on rr.company_id=vv.company_id and rr.version_id=vv.id where h.company_id=target_company and h.family='process_screen';if check_process and p->'process'is distinct from coalesce(actual,'null'::jsonb)then raise exception 'current process proof changed'using errcode='23505';end if;
select coalesce(jsonb_agg(v.export_text::jsonb||jsonb_build_object('review',r.payload)order by v.id),'[]')into bound from neuvetra.corporate_inventory_versions v left join neuvetra.corporate_inventory_reviews r on r.company_id=v.company_id and r.version_id=v.id where v.company_id=target_company and v.id::text<>p#>>'{coverageVersion,id}'and v.id::text in(select distinct id from(select p#>>'{fleet,version,activity,coverageVersionId}'id union all select p#>>'{stationary,version,activity,coverageVersionId}'union all select p#>>'{fugitive,version,activity,coverageVersionId}'union all select p#>>'{process,version,activity,binding,coverageVersionId}')q);if p->'boundCoverageVersions'is distinct from bound then raise exception 'bound corporate proof mismatch'using errcode='22023';end if;
if p->'policy'<>'null'::jsonb and p->'policy'is distinct from neuvetra.m78_policy()then raise exception 'unadmitted policy'using errcode='22023';end if;if octet_length(neuvetra.m67_canonical(p))>4000000 then raise exception 'proof capacity exceeded'using errcode='22023';end if;
end $$;

create function neuvetra.m78_sorted_strings(a jsonb,maximum integer,kind text)returns void language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare x jsonb;expected jsonb;begin if jsonb_typeof(a)is distinct from 'array'or jsonb_array_length(a)>maximum then raise exception 'array capacity'using errcode='22023';end if;for x in select value from jsonb_array_elements(a)loop if jsonb_typeof(x)is distinct from 'string'then raise exception 'string required'using errcode='22023';end if;if kind='uuid'and(x#>>'{}')!~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'then raise exception 'UUID required'using errcode='22023';elsif kind='id'then perform neuvetra.m77_id(x);end if;end loop;select coalesce(jsonb_agg(x order by x#>>'{}'collate "C"),'[]')into expected from(select distinct value x from jsonb_array_elements(a))q;if a is distinct from expected then raise exception 'unique sorted array required'using errcode='22023';end if;end $$;
create function neuvetra.m78_validate_activity(family text,a jsonb,c jsonb)returns void language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare b jsonb:=a->'binding';d jsonb;x jsonb;k text;begin
if family='process_screen'then perform neuvetra.m71_keys(a,'profile,binding,declaration,locations,assessments,gasCoverage,evidenceStatements,manualConfirmation');if a->>'profile'is distinct from 'synthetic-process-screen-v1'or jsonb_typeof(a->'manualConfirmation')is distinct from 'boolean'then raise exception 'process profile'using errcode='22023';end if;
elsif family='inventory'then perform neuvetra.m71_keys(a,'profile,binding,note');if a->>'profile'is distinct from 'synthetic-scope1-inventory-v1'then raise exception 'inventory profile'using errcode='22023';end if;perform neuvetra.m76_diesel_text(a->'note',2000);else raise exception 'family required'using errcode='22023';end if;
perform neuvetra.m71_keys(b,'coverageVersionId,coverageVersionSha256,processCoverageItemId,period');if b->'coverageVersionId'is distinct from c->'id'or b->'coverageVersionSha256'is distinct from c->'versionSha256'or b->'period'is distinct from '{"start":"2025-01-01","endExclusive":"2026-01-01"}'::jsonb or b->'period'is distinct from c#>'{snapshot,period}'or not exists(select 1 from jsonb_array_elements(c#>'{snapshot,coverageItems}')x where x->'id'=b->'processCoverageItemId'and x->>'domain'='process'and x->'entityId'='null'::jsonb and x->'sourceId'='null'::jsonb)then raise exception 'exact corporate/process coverage binding required'using errcode='22023';end if;
if family='inventory'then return;end if;
d:=a->'declaration';if d<>'null'::jsonb then perform neuvetra.m71_keys(d,'completeness,coveredEntityIds,coveredFacilityIds,allControlledOperationsIncluded,discoveryBasis');if coalesce(d->>'completeness','')not in('unknown','partial','declared_complete')or jsonb_typeof(d->'allControlledOperationsIncluded')is distinct from 'boolean'then raise exception 'discovery declaration required'using errcode='22023';end if;perform neuvetra.m78_sorted_strings(d->'coveredEntityIds',150,'uuid');perform neuvetra.m78_sorted_strings(d->'coveredFacilityIds',150,'uuid');perform neuvetra.m76_diesel_text(d->'discoveryBasis',2000);if length(d->>'discoveryBasis')<20 then raise exception 'discovery basis required'using errcode='22023';end if;end if;
foreach k in array array['locations','assessments','gasCoverage','evidenceStatements']loop if jsonb_typeof(a->k)is distinct from 'array'or jsonb_array_length(a->k)>(case k when 'locations'then 25 when 'gasCoverage'then 7 else 100 end)then raise exception 'process capacity'using errcode='22023';end if;end loop;
for x in select value from jsonb_array_elements(a->'locations')loop perform neuvetra.m71_keys(x,'rowId,entityId,facilityId,operationId,businessActivities,equipmentAndMaterials,controlExplanation,evidenceReferences');perform neuvetra.m78_sorted_strings(jsonb_build_array(x->'rowId'),1,'uuid');perform neuvetra.m78_sorted_strings(jsonb_build_array(x->'entityId'),1,'uuid');if(x->'facilityId'='null'::jsonb)=(x->'operationId'='null'::jsonb)then raise exception 'facility or operation required'using errcode='22023';end if;if x->'facilityId'<>'null'::jsonb then perform neuvetra.m78_sorted_strings(jsonb_build_array(x->'facilityId'),1,'uuid');else perform neuvetra.m77_id(x->'operationId');end if;perform neuvetra.m76_diesel_text(x->'businessActivities',2000);perform neuvetra.m76_diesel_text(x->'equipmentAndMaterials',2000);perform neuvetra.m76_diesel_text(x->'controlExplanation',2000);perform neuvetra.m78_sorted_strings(x->'evidenceReferences',100,'id');end loop;
for x in select value from jsonb_array_elements(a->'assessments')loop perform neuvetra.m71_keys(x,'rowId,category,discoveredSourceId,locationRowIds,disposition,reason,evidenceReferences');perform neuvetra.m78_sorted_strings(jsonb_build_array(x->'rowId'),1,'uuid');if coalesce(x->>'category','')not in('mineral_products','chemical_production','metal_production','oil_and_gas','waste_treatment','agricultural_biological','other_direct_process')or coalesce(x->>'disposition','')not in('unknown','indicated','not_applicable_proposed')or(x->>'disposition'='indicated')=(x->'discoveredSourceId'='null'::jsonb)then raise exception 'process assessment required'using errcode='22023';end if;if x->'discoveredSourceId'<>'null'::jsonb then perform neuvetra.m77_id(x->'discoveredSourceId');end if;perform neuvetra.m78_sorted_strings(x->'locationRowIds',25,'uuid');perform neuvetra.m78_sorted_strings(x->'evidenceReferences',100,'id');if x->'reason'<>'null'::jsonb then perform neuvetra.m76_diesel_text(x->'reason',2000);end if;end loop;
for x in select value from jsonb_array_elements(a->'gasCoverage')loop perform neuvetra.m71_keys(x,'gasGroup,state,sourceIds,discoveredSourceIds,locationRowIds,reason,evidenceReferences');if coalesce(x->>'gasGroup','')not in('CO2','CH4','N2O','HFCs','PFCs','SF6','NF3')or coalesce(x->>'state','')not in('unknown','indicated','not_applicable_proposed','covered_by_sources')then raise exception 'gas applicability required'using errcode='22023';end if;perform neuvetra.m78_sorted_strings(x->'sourceIds',150,'uuid');perform neuvetra.m78_sorted_strings(x->'discoveredSourceIds',100,'id');perform neuvetra.m78_sorted_strings(x->'locationRowIds',25,'uuid');perform neuvetra.m78_sorted_strings(x->'evidenceReferences',100,'id');if x->'reason'<>'null'::jsonb then perform neuvetra.m76_diesel_text(x->'reason',2000);end if;if x->>'state'='covered_by_sources'and jsonb_array_length(x->'sourceIds')=0 or x->>'state'='indicated'and jsonb_array_length(x->'discoveredSourceIds')=0 or x->>'state'<>'indicated'and jsonb_array_length(x->'discoveredSourceIds')<>0 or x->>'state'='not_applicable_proposed'and jsonb_array_length(x->'sourceIds')<>0 then raise exception 'gas state source conflict'using errcode='22023';end if;end loop;
for x in select value from jsonb_array_elements(a->'evidenceStatements')loop perform neuvetra.m71_keys(x,'reference,issuer,description,issuedOn,purpose,entityId,facilityId');perform neuvetra.m77_id(x->'reference');perform neuvetra.m76_diesel_text(x->'issuer',120);perform neuvetra.m76_diesel_text(x->'description',2000);if length(x->>'description')<20 or coalesce(x->>'purpose','')not in('business_activity','process_inspection','offsite_discovery')or to_char((x->>'issuedOn')::date,'YYYY-MM-DD')is distinct from x->>'issuedOn'then raise exception 'dated statement required'using errcode='22023';end if;perform neuvetra.m78_sorted_strings(jsonb_build_array(x->'entityId'),1,'uuid');if x->'facilityId'<>'null'::jsonb then perform neuvetra.m78_sorted_strings(jsonb_build_array(x->'facilityId'),1,'uuid');end if;end loop;
foreach k in array array['locations','assessments','gasCoverage','evidenceStatements']loop perform neuvetra.m78_sorted_strings((select coalesce(jsonb_agg(x->case k when 'gasCoverage'then 'gasGroup'when 'evidenceStatements'then 'reference'else 'rowId'end order by n),'[]')from jsonb_array_elements(a->k)with ordinality q(x,n)),100,'text');end loop;if jsonb_array_length(a->'gasCoverage')<>7 then raise exception 'all seven gas groups required'using errcode='22023';end if;
perform neuvetra.m78_sorted_strings((select coalesce(jsonb_agg(x->'discoveredSourceId'order by x->>'discoveredSourceId'collate "C"),'[]')from jsonb_array_elements(a->'assessments')x where x->'discoveredSourceId'<>'null'::jsonb),100,'id');if octet_length(neuvetra.m67_canonical(a))>200000 then raise exception 'activity capacity exceeded'using errcode='22023';end if;
end $$;

create function neuvetra.m78_process_findings(a jsonb,c jsonb)returns jsonb language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare out jsonb:='[]';d jsonb:=a->'declaration';x jsonb;l jsonb;e jsonb;g jsonb;id text;k text;group_rows jsonb;locations jsonb;begin
if d='null'::jsonb or d->>'completeness'<>'declared_complete'or d->'allControlledOperationsIncluded'<>'true'::jsonb or a->'manualConfirmation'<>'true'::jsonb then out:=out||jsonb_build_array(neuvetra.m78_finding('process_discovery_incomplete','Complete discovery and evidence confirmation are required.',null,'process_screen'));end if;
select coalesce(jsonb_agg(x->'rowId'order by x->>'rowId'collate "C"),'[]')into locations from jsonb_array_elements(a->'locations')x;
if d<>'null'::jsonb and(d->'coveredEntityIds'is distinct from(select jsonb_agg(x->'id'order by x->>'id'collate "C")from jsonb_array_elements(c#>'{snapshot,entities}')x)or d->'coveredFacilityIds'is distinct from coalesce((select jsonb_agg(x->'id'order by x->>'id'collate "C")from jsonb_array_elements(c#>'{snapshot,facilities}')x),'[]'))then out:=out||jsonb_build_array(neuvetra.m78_finding('process_scope_incomplete','Discovery must cover every retained entity and location.',null,'process_screen'));end if;
for x in select value from jsonb_array_elements(c#>'{snapshot,facilities}')loop if not exists(select 1 from jsonb_array_elements(a->'locations')l where l->'facilityId'=x->'id'and l->'entityId'=x->'entityId')then out:=out||jsonb_build_array(neuvetra.m78_finding('process_location_missing','Retained location has no process inspection.',x->>'id','process_screen'));end if;end loop;
for x in select value from jsonb_array_elements(a->'evidenceStatements')loop if not exists(select 1 from jsonb_array_elements(c#>'{snapshot,entities}')e where e->'id'=x->'entityId')or x->'facilityId'<>'null'::jsonb and not exists(select 1 from jsonb_array_elements(c#>'{snapshot,facilities}')f where f->'id'=x->'facilityId'and f->'entityId'=x->'entityId')then out:=out||jsonb_build_array(neuvetra.m78_finding('process_evidence_location_unknown','Statement location does not resolve.',x->>'reference','process_screen'));end if;end loop;
for l in select value from jsonb_array_elements(a->'locations')loop
 if not exists(select 1 from jsonb_array_elements(c#>'{snapshot,entities}')e where e->'id'=l->'entityId')or l->'facilityId'<>'null'::jsonb and not exists(select 1 from jsonb_array_elements(c#>'{snapshot,facilities}')f where f->'id'=l->'facilityId'and f->'entityId'=l->'entityId')then out:=out||jsonb_build_array(neuvetra.m78_finding('process_location_unknown','Inspection location does not resolve.',l->>'rowId','process_screen'));end if;
 if jsonb_array_length(l->'evidenceReferences')=0 or exists(select 1 from jsonb_array_elements_text(l->'evidenceReferences')r where not exists(select 1 from jsonb_array_elements(a->'evidenceStatements')e where e->>'reference'=r and e->'entityId'=l->'entityId'and e->'facilityId'=l->'facilityId'))or not exists(select 1 from jsonb_array_elements(a->'evidenceStatements')e where l->'evidenceReferences'? (e->>'reference')and e->>'purpose'='business_activity')or not exists(select 1 from jsonb_array_elements(a->'evidenceStatements')e where l->'evidenceReferences'?(e->>'reference')and e->>'purpose'=case when l->'facilityId'='null'::jsonb then 'offsite_discovery'else 'process_inspection'end)then out:=out||jsonb_build_array(neuvetra.m78_finding('process_location_evidence_missing','Inspection requires retained activity and location-matched discovery evidence.',l->>'rowId','process_screen'));end if;
end loop;
for x in select value from jsonb_array_elements(c#>'{snapshot,entities}')loop if not exists(select 1 from jsonb_array_elements(a->'evidenceStatements')e where e->'entityId'=x->'id'and e->'facilityId'='null'::jsonb and e->>'purpose'='offsite_discovery')then out:=out||jsonb_build_array(neuvetra.m78_finding('process_offsite_evidence_missing','Every entity needs explicit controlled non-facility discovery evidence.',x->>'id','process_screen'));end if;end loop;
foreach k in array array['mineral_products','chemical_production','metal_production','oil_and_gas','waste_treatment','agricultural_biological','other_direct_process']loop select coalesce(jsonb_agg(x),'[]')into group_rows from jsonb_array_elements(a->'assessments')x where x->>'category'=k and x->'discoveredSourceId'='null'::jsonb;if jsonb_array_length(group_rows)<>1 or group_rows#>'{0,locationRowIds}'is distinct from locations then out:=out||jsonb_build_array(neuvetra.m78_finding('process_category_scope_incomplete','Every category requires one full-discovery assessment.',k,'process_screen'));end if;end loop;
for x in select value from jsonb_array_elements(a->'assessments')loop
 if x->>'disposition'<>'not_applicable_proposed'then out:=out||jsonb_build_array(neuvetra.m78_finding(case when x->>'disposition'='indicated'then 'process_method_unsupported'else 'process_applicability_unknown'end,'Process applicability or indicated method remains unresolved.',coalesce(nullif(x->>'discoveredSourceId',''),x->>'rowId'),'process_screen'));end if;
 if x->'reason'='null'::jsonb or jsonb_array_length(x->'evidenceReferences')=0 or exists(select 1 from jsonb_array_elements_text(x->'evidenceReferences')r where not exists(select 1 from jsonb_array_elements(a->'evidenceStatements')e where e->>'reference'=r))or exists(select 1 from jsonb_array_elements_text(x->'locationRowIds')r where not exists(select 1 from jsonb_array_elements(a->'locations')l where l->>'rowId'=r))then out:=out||jsonb_build_array(neuvetra.m78_finding('process_assessment_evidence_missing','Assessment rationale and references must resolve.',x->>'rowId','process_screen'));end if;
 for l in select value from jsonb_array_elements(a->'locations')l where x->'locationRowIds'?(l->>'rowId')loop if not exists(select 1 from jsonb_array_elements(a->'evidenceStatements')e where x->'evidenceReferences'?(e->>'reference')and e->'entityId'=l->'entityId'and e->'facilityId'=l->'facilityId'and e->>'purpose'=case when l->'facilityId'='null'::jsonb then 'offsite_discovery'else 'process_inspection'end)then out:=out||jsonb_build_array(neuvetra.m78_finding('process_assessment_location_evidence_missing','Assessment lacks inspected-location support.',x->>'rowId','process_screen'));end if;end loop;
end loop;
for g in select value from jsonb_array_elements(a->'gasCoverage')loop
 if g->>'state'in('unknown','indicated')then out:=out||jsonb_build_array(neuvetra.m78_finding(case when g->>'state'='unknown'then 'gas_applicability_unknown'else 'indicated_gas_source_unsupported'end,'Gas applicability or indicated source is unresolved.',g->>'gasGroup','process_screen'));end if;
 if g->'reason'='null'::jsonb or g->'locationRowIds'is distinct from locations or exists(select 1 from jsonb_array_elements_text(g->'evidenceReferences')r where not exists(select 1 from jsonb_array_elements(a->'evidenceStatements')e where e->>'reference'=r))or exists(select 1 from jsonb_array_elements_text(g->'sourceIds')r where not exists(select 1 from jsonb_array_elements(c#>'{snapshot,sources}')s where s->>'id'=r and s->>'domain'in('stationary_combustion','mobile_combustion','fugitive','process')))then out:=out||jsonb_build_array(neuvetra.m78_finding('gas_scope_evidence_missing','Every gas group needs exact source and full-discovery evidence.',g->>'gasGroup','process_screen'));end if;
 for x in select value from jsonb_array_elements(c#>'{snapshot,entities}')loop if not exists(select 1 from jsonb_array_elements(a->'evidenceStatements')e where g->'evidenceReferences'?(e->>'reference')and e->'entityId'=x->'id'and e->'facilityId'='null'::jsonb and e->>'purpose'='offsite_discovery')then out:=out||jsonb_build_array(neuvetra.m78_finding('gas_offsite_evidence_missing','Gas scope requires explicit non-facility discovery evidence for every entity.',g->>'gasGroup','process_screen'));end if;end loop;
 for l in select value from jsonb_array_elements(a->'locations')loop if not exists(select 1 from jsonb_array_elements(a->'evidenceStatements')e where g->'evidenceReferences'?(e->>'reference')and e->'entityId'=l->'entityId'and e->'facilityId'=l->'facilityId'and e->>'purpose'=case when l->'facilityId'='null'::jsonb then 'offsite_discovery'else 'process_inspection'end)then out:=out||jsonb_build_array(neuvetra.m78_finding('gas_location_evidence_missing','Gas applicability lacks retained inspected-location support.',g->>'gasGroup','process_screen'));end if;end loop;
end loop;
for x in select value from jsonb_array_elements(c#>'{snapshot,sources}')where value->>'domain'='process'loop out:=out||jsonb_build_array(neuvetra.m78_finding('corporate_process_source_unsupported','Corporate process source requires a supported method.',x->>'id','process_screen'));end loop;return out;
end $$;

create function neuvetra.m78_gas_sources(p jsonb,gas_group text)returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select coalesce(jsonb_agg(x order by n),'[]')from jsonb_array_elements(p->'sourceVersions')with ordinality q(x,n)where case when x->>'family'='fugitive'then gas_group='HFCs'and(x#>>'{version,activity,gas}'like 'HFC-%'or x#>>'{version,activity,gas}'='R-410A')or gas_group=x#>>'{version,activity,gas}'else gas_group in('CO2','CH4','N2O')end$$;
create function neuvetra.m78_screen_findings(a jsonb,p jsonb)returns jsonb language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare out jsonb:=neuvetra.m78_process_findings(a,p->'coverageVersion');f jsonb;g jsonb;x jsonb;actual jsonb;d text;begin
for f in select value from jsonb_array_elements(p#>'{coverageVersion,findings}')where value->>'code'in('unsupported_consolidation','unsupported_geography','unsupported_temporal_allocation','unsupported_boundary_relationship','control_evidence_missing','boundary_unreconciled','boundary_basis_missing','boundary_assertion_unverified')loop out:=out||jsonb_build_array(neuvetra.m78_finding('corporate_scope1_boundary_blocked',f->>'message',f->>'recordId','process_screen'));end loop;
if p#>>'{coverageVersion,review,decision}'is distinct from 'accepted_bounded_internal'then out:=out||jsonb_build_array(neuvetra.m78_finding('corporate_review_required','Current corporate boundary requires exact review.',null,'process_screen'));end if;
for g in select value from jsonb_array_elements(a->'gasCoverage')loop actual:=neuvetra.m78_gas_sources(p,g->>'gasGroup');if jsonb_array_length(actual)>0 and g->>'state'<>'covered_by_sources'or g->>'state'='covered_by_sources'and g->'sourceIds'is distinct from coalesce((select jsonb_agg(x#>'{version,activity,binding,sourceId}'order by x#>>'{version,activity,binding,sourceId}'collate "C")from jsonb_array_elements(actual)x),'[]')then out:=out||jsonb_build_array(neuvetra.m78_finding('gas_source_coverage_conflict','Gas applicability must name every exact source in the discovered population.',g->>'gasGroup','process_screen'));end if;if g->>'state'<>'covered_by_sources'then continue;end if;
foreach d in array array['fleet','stationary','fugitive']loop if p#>>array[d,'reconciliation','status']is distinct from 'reconciled_bounded_synthetic'or p#>>array[d,'review','decision']is distinct from 'accepted_bounded_reconciliation'then out:=out||jsonb_build_array(neuvetra.m78_finding('gas_physical_population_unreconciled','Positive gas coverage requires independently reconciled complete physical populations.',g->>'gasGroup','process_screen'));end if;end loop;
for x in select value from jsonb_array_elements(actual)loop if x#>'{version,calculation}'='null'::jsonb or x#>>'{version,review,decision}'is distinct from 'accepted_bounded_internal'or x#>'{version,activity,binding,coverageVersionId}'is distinct from p#>'{coverageVersion,id}'or x#>'{version,activity,binding,coverageVersionSha256}'is distinct from p#>'{coverageVersion,versionSha256}'then out:=out||jsonb_build_array(neuvetra.m78_finding('gas_source_incomplete','Positive gas coverage requires current exact supported source review.',x#>>'{version,activity,binding,sourceId}','process_screen'));end if;end loop;
end loop;return out;end $$;
create function neuvetra.m78_corporate_findings(p jsonb)returns jsonb language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare out jsonb:='[]';c jsonb:=p->'coverageVersion';s jsonb:=c->'snapshot';deps jsonb:=neuvetra.m78_dependencies(p,'inventory');f jsonb;row jsonb;domain text;source_id text;matched jsonb;candidate boolean;group_row boolean;discovery boolean;supported boolean;d jsonb;classification text;resolution jsonb;process_accepted boolean;begin
process_accepted:=p#>>'{process,review,decision}'='accepted_bounded_process_screen'and p#>'{process,version,activity,binding,coverageVersionId}'=c->'id'and p#>'{process,version,activity,binding,coverageVersionSha256}'=c->'versionSha256'and p#>'{process,version,dependencies}'=neuvetra.m78_dependencies(p,'process_screen')and not exists(select 1 from jsonb_array_elements(neuvetra.m78_screen_findings(p#>'{process,version,activity}',p))x where x->>'classification'='functional_blocker');
for f in select value from jsonb_array_elements(c->'findings')loop row:=null;select x into row from jsonb_array_elements((s->'entities')||(s->'facilities')||(s->'relationships')||(s->'boundaryDecisions')||(s->'coverageItems')||(s->'requirements'))x where x->'id'=f->'recordId'limit 1;domain:=row->>'domain';classification:='functional_blocker';resolution:=null;
if f->>'code'in('unsupported_consolidation','unsupported_geography','unsupported_temporal_allocation','unsupported_boundary_relationship','control_evidence_missing','boundary_unreconciled','boundary_basis_missing','boundary_assertion_unverified')then classification:='functional_blocker';elsif f->>'code'in('synthetic_evidence_not_sufficient','methods_not_released')then classification:='release_blocker';elsif f->>'code'in('requirements_not_determined','requirement_unknown','requirement_conflicting')or domain is not null and domain not in('stationary_combustion','mobile_combustion','fugitive','process')then classification:='corporate_gap';elsif domain in('stationary_combustion','mobile_combustion','fugitive','process')then
source_id:=row->>'sourceId';select coalesce(jsonb_agg(x),'[]')into matched from jsonb_array_elements(p->'sourceVersions')x where x#>>'{version,activity,binding,sourceId}'=source_id;candidate:=jsonb_array_length(matched)=1 and matched#>>'{0,version,review,decision}'='accepted_bounded_internal'and matched#>'{0,version,calculation}'<>'null'::jsonb and matched#>'{0,version,activity,binding,coverageVersionId}'=c->'id'and matched#>'{0,version,activity,binding,coverageVersionSha256}'=c->'versionSha256';group_row:=row->'entityId'='null'::jsonb and row->'sourceId'='null'::jsonb;d:=p->case domain when 'mobile_combustion'then 'fleet'when 'stationary_combustion'then 'stationary'else 'fugitive'end;discovery:=group_row and domain<>'process'and d#>>'{reconciliation,status}'='reconciled_bounded_synthetic'and d#>>'{review,decision}'='accepted_bounded_reconciliation'and d->'version'<>'null'::jsonb and d#>'{version,activity,coverageVersionId}'=c->'id';supported:=case when domain='process'then group_row and process_accepted when source_id is not null then candidate else discovery end;
if supported and f->>'code'in('activity_unknown','evidence_incomplete','method_unsupported','screening_assertion_unverified')then classification:='resolved_bounded';resolution:=jsonb_build_object('ruleId',case when domain='process'then 'accepted_process_screen'when source_id is not null then 'current_reviewed_source'else 'current_reviewed_discovery'end,'pins',case when domain='process'then jsonb_build_array(deps->'processVersionPin',deps->'processReviewPin')when source_id is not null then jsonb_build_array(neuvetra.m78_pin(matched#>'{0,version}'),neuvetra.m78_pin(matched#>'{0,version,review}',true))else jsonb_build_array(neuvetra.m78_pin(d->'version'),neuvetra.m78_pin(d->'review',true))end);end if;end if;
out:=out||jsonb_build_array(neuvetra.m78_finding(f->>'code',f->>'message',f->>'recordId','corporate',classification,resolution));end loop;return out;end $$;

create function neuvetra.m78_gas_lines(rows jsonb)returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select coalesce(jsonb_agg(jsonb_build_object('gas',gas,'gasKind',kind,'massKgExact',neuvetra.m76_diesel_exact(mass),'kgCo2eExact',neuvetra.m76_diesel_exact(co2e))order by gas collate "C"),'[]')from(select x->>'gas'gas,min(x->>'gasKind')kind,sum((x->>'massKgExact')::numeric)mass,sum((x->>'co2eKgExact')::numeric)co2e from jsonb_array_elements(rows)x group by x->>'gas')q$$;
create function neuvetra.m78_rollup_row(id text,label text,rows jsonb)returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select jsonb_build_object('id',id,'label',label,'kgCo2eExact',neuvetra.m76_diesel_exact(n),'kgCo2eDisplay',neuvetra.m76_diesel_display(n),'gasLines',neuvetra.m78_gas_lines(rows))from(select coalesce(sum((x->>'co2eKgExact')::numeric),0)n from jsonb_array_elements(rows)x)q$$;
create function neuvetra.m78_rollup(p jsonb,rows jsonb)returns jsonb language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare sources jsonb:='[]';facilities jsonb:='[]';entities jsonb:='[]';x jsonb;filtered jsonb;n numeric;displayed numeric;begin
for x in select value from jsonb_array_elements(p#>'{coverageVersion,snapshot,sources}')loop select coalesce(jsonb_agg(r),'[]')into filtered from jsonb_array_elements(rows)r where r->'sourceId'=x->'id';if jsonb_array_length(filtered)>0 then sources:=sources||jsonb_build_array(neuvetra.m78_rollup_row(x->>'id',x->>'name',filtered));end if;end loop;
for x in select value from jsonb_array_elements(p#>'{coverageVersion,snapshot,facilities}')loop select coalesce(jsonb_agg(r),'[]')into filtered from jsonb_array_elements(rows)r where r->'facilityId'=x->'id';if jsonb_array_length(filtered)>0 then facilities:=facilities||jsonb_build_array(neuvetra.m78_rollup_row(x->>'id',x->>'name',filtered));end if;end loop;
for x in select value from jsonb_array_elements(p#>'{coverageVersion,snapshot,entities}')loop select coalesce(jsonb_agg(r),'[]')into filtered from jsonb_array_elements(rows)r where r->'entityId'=x->'id';if jsonb_array_length(filtered)>0 then entities:=entities||jsonb_build_array(neuvetra.m78_rollup_row(x->>'id',x->>'legalName',filtered));end if;end loop;
select coalesce(sum((x->>'co2eKgExact')::numeric),0)into n from jsonb_array_elements(rows)x;select coalesce(sum((x->>'kgCo2eDisplay')::numeric),0)into displayed from jsonb_array_elements(sources)x;return jsonb_build_object('gasLines',neuvetra.m78_gas_lines(rows),'sourceRows',sources,'facilityRows',facilities,'entityRows',entities,'company',jsonb_build_object('kgCo2eExact',neuvetra.m76_diesel_exact(n),'kgCo2eDisplay',neuvetra.m76_diesel_display(n),'rounding','half_even_4dp'),'displayRoundingDelta',neuvetra.m76_diesel_exact(neuvetra.m76_diesel_display(n)::numeric-displayed));end $$;

create function neuvetra.m78_reconciliation(p jsonb)returns jsonb language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare deps jsonb:=neuvetra.m78_dependencies(p,'inventory');findings jsonb:=neuvetra.m78_corporate_findings(p);s jsonb:=p#>'{coverageVersion,snapshot}';union_rows jsonb:='[]';rows jsonb:='[]';subtotal jsonb;body jsonb;x jsonb;v jsonb;c jsonb;src jsonb;screen jsonb;b jsonb;r jsonb;g jsonb;e jsonb;input jsonb;old text;id text;family text;asset text;key text;d text;actual_ids jsonb;method text;source_rows jsonb;mass numeric;co2e numeric;expected numeric;total numeric;physical_ids jsonb:='{}';evidence_keys jsonb:='{}';meters jsonb:='{}';policy_blocked boolean;blocked boolean;begin
if p#>>'{coverageVersion,review,decision}'is distinct from 'accepted_bounded_internal'then findings:=findings||jsonb_build_array(neuvetra.m78_finding('corporate_review_required','Current exact corporate coverage requires separate review.'));end if;if p#>>'{process,review,decision}'is distinct from 'accepted_bounded_process_screen'then findings:=findings||jsonb_build_array(neuvetra.m78_finding('process_review_required','Current exact process discovery requires separate acceptance.'));end if;
if p->'process'<>'null'::jsonb then findings:=findings||neuvetra.m78_screen_findings(p#>'{process,version,activity}',p);if p#>'{process,version,dependencies}'is distinct from neuvetra.m78_dependencies(p,'process_screen')then findings:=findings||jsonb_build_array(neuvetra.m78_finding('process_dependencies_stale','Process screen requires current source and discovery dependencies.'));end if;if p#>'{process,version,activity,binding,coverageVersionId}'is distinct from p#>'{coverageVersion,id}'or p#>'{process,version,activity,binding,coverageVersionSha256}'is distinct from p#>'{coverageVersion,versionSha256}'then findings:=findings||jsonb_build_array(neuvetra.m78_finding('process_stale','Process screen is bound to older corporate coverage.'));end if;
for g in select value from jsonb_array_elements(p#>'{process,version,activity,gasCoverage}')loop select coalesce(jsonb_agg(x#>'{version,activity,binding,sourceId}'order by x#>>'{version,activity,binding,sourceId}'collate "C"),'[]')into actual_ids from jsonb_array_elements(neuvetra.m78_gas_sources(p,g->>'gasGroup'))x;if jsonb_array_length(actual_ids)>0 and g->>'state'<>'covered_by_sources'or g->>'state'='covered_by_sources'and g->'sourceIds'is distinct from actual_ids then findings:=findings||jsonb_build_array(neuvetra.m78_finding('gas_source_coverage_conflict','Gas applicability does not match exact current source identities.',g->>'gasGroup'));end if;end loop;end if;
foreach d in array array['fleet','stationary','fugitive']loop if p#>>array[d,'reconciliation','status']is distinct from 'reconciled_bounded_synthetic'or p#>array[d,'version']='null'::jsonb or p#>>array[d,'review','decision']is distinct from 'accepted_bounded_reconciliation'then findings:=findings||jsonb_build_array(neuvetra.m78_finding('discovery_blocked','Complete physical discovery and exact review are required.',d));end if;for x in select value from jsonb_array_elements(p#>array[d,'reconciliation','findings'])loop if x->'blocking'='false'::jsonb then continue;end if;findings:=findings||jsonb_build_array(neuvetra.m78_finding(x->>'code',x->>'message',coalesce(x->>'rowKey',x->>'sourceId'),d));end loop;end loop;
for x in select value from jsonb_array_elements(s->'sources')where value->>'domain'in('stationary_combustion','mobile_combustion','fugitive','process')loop union_rows:=union_rows||jsonb_build_array(jsonb_build_object('sourceId',x->'id','physicalId',coalesce((select r->'physicalId'from jsonb_array_elements(deps->'sourcePins')r where r->'sourceId'=x->'id'limit 1),'null'::jsonb),'family',x->'domain','entityId',x->'entityId','facilityId',x->'facilityId'));end loop;
for r in select value from jsonb_array_elements(p#>'{fleet,reconciliation,rows}')where value->'sourceId'='null'::jsonb loop union_rows:=union_rows||jsonb_build_array(jsonb_build_object('sourceId',null,'physicalId',r->'assetId','family','mobile_combustion','entityId',null,'facilityId',null));end loop;
for r in select value from jsonb_array_elements(p#>'{stationary,reconciliation,rows}')where value->'sourceId'='null'::jsonb loop union_rows:=union_rows||jsonb_build_array(jsonb_build_object('sourceId',null,'physicalId',r->'equipmentId','family','stationary_combustion','entityId',null,'facilityId',null));end loop;
for r in select value from jsonb_array_elements(p#>'{fugitive,reconciliation,assets}')where value->'sourceId'='null'::jsonb loop union_rows:=union_rows||jsonb_build_array(jsonb_build_object('sourceId',null,'physicalId',r->'assetId','family','fugitive','entityId',r->'entityId','facilityId',r->'facilityId'));end loop;
for x in select value from jsonb_array_elements(p->'sourceVersions')loop v:=x->'version';family:=x->>'family';id:=v#>>'{activity,binding,sourceId}';select r into src from jsonb_array_elements(s->'sources')r where r->>'id'=id;select r into screen from jsonb_array_elements(s->'coverageItems')r where r->>'sourceId'=id;select r into b from jsonb_array_elements(s->'boundaryDecisions')r where r->'id'=v#>'{activity,binding,boundaryDecisionId}';
if(select count(*)from jsonb_array_elements(p->'sourceVersions')r where r#>>'{version,activity,binding,sourceId}'=id)<>1 then findings:=findings||jsonb_build_array(neuvetra.m78_finding('duplicate_effective_source','Source has multiple effective workpapers.',id));end if;
if src is null or src->'entityId'is distinct from v#>'{activity,binding,entityId}'or src->'facilityId'is distinct from v#>'{activity,binding,facilityId}'then findings:=findings||jsonb_build_array(neuvetra.m78_finding('source_binding_conflict','Source/workpaper corporate location differs.',id));end if;
if screen->>'disposition'is distinct from 'included_activity'or b->>'disposition'is distinct from 'included_activity'or b->'reason'='null'::jsonb or coalesce(jsonb_array_length(b->'evidenceRefs'),0)=0 then findings:=findings||jsonb_build_array(neuvetra.m78_finding('source_admission_blocked','Own source screening and entity control must both be supported.',id));end if;
