end loop;
for src in select value from jsonb_array_elements(s->'sources')where value->>'domain'in('stationary_combustion','mobile_combustion','fugitive')loop if not exists(select 1 from jsonb_array_elements(p->'sourceVersions')r where r#>'{version,activity,binding,sourceId}'=src->'id')then findings:=findings||jsonb_build_array(neuvetra.m78_finding('source_workpaper_missing','Corporate source has no effective workpaper.',src->>'id'));end if;end loop;
