create function neuvetra.m78_report_statements(s jsonb)returns jsonb language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare all_rows jsonb:=s#>'{version,statements}'||coalesce(s#>'{proof,process,version,statements}','[]'::jsonb);x jsonb;e jsonb;begin
for x in select value from jsonb_array_elements(s#>'{proof,sourceVersions}')loop for e in select value from jsonb_array_elements(jsonb_build_array(x#>'{version,statement}',x#>'{version,fuelStatement}',x#>'{version,mileageStatement}')||coalesce(x#>'{version,statements}','[]'::jsonb))where value is not null and value<>'null'::jsonb loop all_rows:=all_rows||jsonb_build_array(e||jsonb_build_object('description',coalesce(e->>'description',e#>>'{input,description}','Retained source activity statement.')));end loop;end loop;
return(select coalesce(jsonb_agg(x order by x->>'id'collate "C"),'[]')from(select distinct on(x->>'id')x from jsonb_array_elements(all_rows)with ordinality q(x,n)order by x->>'id',n desc)r);end $$;
create function neuvetra.m78_report_table(title text,rows jsonb)returns text language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select '<h2>'||title||'</h2><table><thead><tr><th>Name / retained identity</th><th>Gross kg CO2e</th></tr></thead><tbody>'||coalesce((select string_agg('<tr><td data-label="Name / retained identity">'||neuvetra.m75_html_escape(r->>'label')||'<br>'||neuvetra.m75_html_escape(r->>'id')||'</td><td data-label="Gross kg CO2e">'||neuvetra.m75_html_escape(r->>'kgCo2eDisplay')||'</td></tr>',''order by n)from jsonb_array_elements(rows)with ordinality q(r,n)),'')||'</tbody></table>'$$;
create function neuvetra.m78_render_report(s jsonb)returns text language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare v jsonb:=s->'version';c jsonb:=s#>'{proof,coverageVersion,snapshot}';r jsonb:=s->'reconciliation';t jsonb;title text;status text;accepted boolean;statements jsonb:=neuvetra.m78_report_statements(s);numbers text;findings text;evidence text;locations text;links text;begin
title:=case when s->>'family'='process_screen'then 'Process-source screening'else 'Gross Scope 1 inventory'end;accepted:=coalesce(s#>>'{review,decision}'in('accepted_bounded_process_screen','accepted_bounded_inventory'),false);status:=case when s->>'family'='process_screen'then case when exists(select 1 from jsonb_array_elements(v->'findings')f where f->>'classification'='functional_blocker')then 'Blocked process discovery'when accepted then 'Reviewed bounded process screen'else 'Process review pending'end when r->>'status'='reconciled_bounded_synthetic'then 'Reconciled synthetic Scope 1 candidate'else 'Scope 1 incomplete'end;t:=coalesce(nullif(r->'totals','null'::jsonb),nullif(r->'knownSourceSubtotal','null'::jsonb));
if t is not null then numbers:='<h2>'||case when r->'totals'<>'null'::jsonb then 'Gross company total'else 'Known-source subtotal — incomplete coverage'end||'</h2><p>'||neuvetra.m75_html_escape(t#>>'{company,kgCo2eDisplay}')||' kg CO2e</p><table><thead><tr><th>Gas</th><th>Emitted kg gas</th><th>Gross kg CO2e exact</th></tr></thead><tbody>'||coalesce((select string_agg('<tr><td data-label="Gas">'||neuvetra.m75_html_escape(g->>'gas')||case when g->>'gasKind'='blend'then ' (blend; constituents not inferred)'else ''end||'</td><td data-label="Emitted kg gas">'||neuvetra.m75_html_escape(g->>'massKgExact')||'</td><td data-label="Gross kg CO2e exact">'||neuvetra.m75_html_escape(g->>'kgCo2eExact')||'</td></tr>',''order by n)from jsonb_array_elements(t->'gasLines')with ordinality q(g,n)),'')||'</tbody></table>'||neuvetra.m78_report_table('Sources',t->'sourceRows')||neuvetra.m78_report_table('Facilities — organizational attribution',t->'facilityRows')||neuvetra.m78_report_table('Entities',t->'entityRows')||'<p>Totals sum unrounded source contributions before half-even display rounding. Displayed company total minus displayed source sum: '||neuvetra.m75_html_escape(t->>'displayRoundingDelta')||' kg CO2e. No offsets or avoided emissions deducted.</p>';else numbers:='<p>No combined company CO2e total is available while compatibility or source coverage is unresolved.</p>';end if;
select coalesce(string_agg('<li>'||neuvetra.m75_html_escape(f->>'classification')||': '||neuvetra.m75_html_escape(f->>'message')||'</li>',''order by n),'')into findings from jsonb_array_elements(coalesce(nullif(r->'findings','null'::jsonb),v->'findings'))with ordinality q(f,n);
select coalesce(string_agg('<section id="statement-'||neuvetra.m75_html_escape(e->>'id')||'"><h3>'||neuvetra.m75_html_escape(e->>'description')||'</h3><p>Locator '||neuvetra.m75_html_escape(e->>'locator')||' · SHA-256 '||neuvetra.m75_html_escape(e->>'sha256')||'</p><details><summary>Exact retained statement</summary><pre>'||neuvetra.m75_html_escape(e->>'text')||'</pre></details></section>',''order by n),'')into evidence from jsonb_array_elements(statements)with ordinality q(e,n);
select coalesce(string_agg('<li>'||neuvetra.m75_html_escape((select e->>'legalName'from jsonb_array_elements(c->'entities')e where e->'id'=f->'entityId'limit 1))||' — '||neuvetra.m75_html_escape(f->>'name')||' · '||neuvetra.m75_html_escape(f->>'id')||'</li>',''order by n),'')into locations from jsonb_array_elements(c->'facilities')with ordinality q(f,n);select coalesce(string_agg('<li><a href="#statement-'||neuvetra.m75_html_escape(e->>'id')||'">'||neuvetra.m75_html_escape(e->>'description')||'</a></li>',''order by n),'')into links from jsonb_array_elements(statements)with ordinality q(e,n);
return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src ''none''; style-src ''unsafe-inline''; base-uri ''none''; form-action ''none''"><title>'||title||'</title><style>body{font:16px/1.5 system-ui;margin:2rem auto;padding:0 1rem;max-width:1000px;color:#172f2c;overflow-wrap:anywhere}table{border-collapse:collapse;width:100%}th,td{padding:.4rem;text-align:left;border-bottom:1px solid #ccd8d0}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.5 monospace;background:#f3f6f3;padding:1rem}@media(max-width:600px){thead{display:none}tr{display:block;margin:.8rem 0}td{display:block}td::before{content:attr(data-label);font-weight:600;margin-right:.5rem}}@media print{body{font-size:10pt;margin:0}tr{break-inside:avoid}}</style></head><body><h1>'||title||' — synthetic internal draft</h1><p>'||neuvetra.m75_html_escape(c->>'companyLabel')||' · calendar 2025 · version '||(v->>'version')||'</p><p>'||neuvetra.m75_html_escape(status)||' · '||case when accepted then 'accepted for bounded internal review'when s->'review'<>'null'::jsonb then 'changes requested'else 'not reviewed'end||'.</p><p>Scope 1 and corporate inventory remain incomplete for release. Candidate methods and factors are not released. Requirements are not determined. No external assurance. Fictional evidence is not original customer evidence.</p>'||numbers||neuvetra.m78_report_detail_sections(s)||'<h2>Retained entities and locations</h2><ul>'||locations||'</ul><h2>Coverage findings and limitations</h2><ul>'||findings||'</ul><h2>Retained evidence</h2><ul>'||links||'</ul>'||evidence||'<details><summary>Exact retained snapshot and provenance</summary><pre>'||neuvetra.m75_html_escape(neuvetra.m67_canonical(s))||'</pre></details></body></html>';end $$;

