create function neuvetra.m78_record_request(target_company uuid,target_stream uuid,family text,kind text,request jsonb,record_id uuid,record_sha text,captured timestamptz)returns void language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$
