declare total bigint;begin select coalesce(sum(octet_length(export_text)+octet_length(neuvetra.m67_canonical(proof))),0)into total from neuvetra.scope1_versions where company_id=target_company;select total+coalesce(sum(octet_length(payload->>'html')+octet_length(payload->>'snapshotJson')),0)into total from neuvetra.scope1_reports where company_id=target_company;if total+extra>30000000 then raise exception 'retained history capacity exceeded'using errcode='54000';end if;end $$;
