if exists(select 1 from jsonb_array_elements(jsonb_build_array(p->'coverageVersion')||(p->'boundCoverageVersions')||coalesce((select jsonb_agg(x->'version')from jsonb_array_elements(p->'sourceVersions')x),'[]'::jsonb)||jsonb_build_array(p#>'{fleet,version}',p#>'{stationary,version}',p#>'{fugitive,version}',p#>'{process,version}'))entry where entry<>'null'::jsonb and((entry->>'createdAt')::timestamptz>captured or coalesce((entry#>>'{review,reviewedAt}')::timestamptz,'-infinity'::timestamptz)>captured))or exists(select 1 from jsonb_array_elements(jsonb_build_array(p#>'{fleet,review}',p#>'{stationary,review}',p#>'{fugitive,review}',p#>'{process,review}'))entry where entry<>'null'::jsonb and(entry->>'reviewedAt')::timestamptz>captured)then raise exception 'dependency chronology exceeds capture'using errcode='22023';end if;if v->'companyId'is distinct from to_jsonb(target_company::text)or v->>'family'is distinct from family or v->'createdBy'is distinct from to_jsonb(actor::text)or captured>clock_timestamp()+interval '2 minutes'or captured<clock_timestamp()-interval '2 minutes'or prior is not null and captured<=(prior->>'createdAt')::timestamptz or v->'streamId'is distinct from coalesce(to_jsonb(target_stream::text),v->'streamId')or v->'version'is distinct from to_jsonb(coalesce((prior->>'version')::integer,0)+1)or v->'previousVersionId'is distinct from coalesce(prior->'id','null'::jsonb)or v->'previousVersionSha256'is distinct from coalesce(prior->'versionSha256','null'::jsonb)or v->'correctionReason'is distinct from request->'correctionReason'or v->'contributorIds'is distinct from neuvetra.m78_contributors(p,prior,actor,family)or v->'dependencies'is distinct from deps or v->'statements'is distinct from statements or v->'findings'is distinct from findings or v->'reconciliation'is distinct from coalesce(rec,'null'::jsonb)or v->>'inputSha256'is distinct from neuvetra.m67_hash(a)or v->>'contentSha256'is distinct from neuvetra.m67_hash(content)or v->>'versionSha256'is distinct from neuvetra.m67_hash(v-array['versionSha256','review'])or v->'synthetic'<>'true'::jsonb or v->>'scope1Completeness'is distinct from 'incomplete'or v->>'corporateCompleteness'is distinct from 'incomplete'or v->'releaseEligible'<>'false'::jsonb or v->>'assurance'is distinct from 'none'or v->'review'<>'null'::jsonb then raise exception 'version semantic integrity'using errcode='22023';end if;
perform neuvetra.m78_capacity(target_company,octet_length(neuvetra.m67_canonical(v))+octet_length(neuvetra.m67_canonical(p)));
if target_stream is null then insert into neuvetra.scope1_heads(id,company_id,family)values((v->>'streamId')::uuid,target_company,family);end if;
for statement in select value from jsonb_array_elements(statements)loop insert into neuvetra.scope1_statements values((statement->>'id')::uuid,target_company,statement,statement->>'sha256',statement->>'text');end loop;
insert into neuvetra.scope1_versions values((v->>'id')::uuid,target_company,(v->>'streamId')::uuid,family,(v->>'version')::integer,(v->>'previousVersionId')::uuid,(a#>>'{binding,coverageVersionId}')::uuid,v,p,v->>'inputSha256',v->>'contentSha256',v->>'versionSha256',actor,captured,neuvetra.m67_canonical(v));update neuvetra.scope1_heads set version_id=(v->>'id')::uuid,revision=(v->>'version')::integer where company_id=target_company and id=(v->>'streamId')::uuid;
if family='process_screen'then for key in select 'process:'||(x->>'discoveredSourceId')from jsonb_array_elements(a->'assessments')x where x->'discoveredSourceId'<>'null'::jsonb union all select 'gas:'||(g->>'gasGroup')||':'||id from jsonb_array_elements(a->'gasCoverage')g,jsonb_array_elements_text(g->'discoveredSourceIds')id loop insert into neuvetra.scope1_process_discoveries values(target_company,2025,key,(v->>'streamId')::uuid,captured)on conflict do nothing;end loop;end if;
perform neuvetra.m78_record_request(target_company,target_stream,family,'save',request,(v->>'id')::uuid,v->>'versionSha256',captured);return(v->>'id')::uuid;end $$;

create function neuvetra.review_scope1_version(target_company uuid,target_stream uuid,family text,request jsonb,r jsonb)returns uuid language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare replay jsonb;v jsonb;p jsonb;head_id uuid;captured timestamptz;actor uuid:=auth.uid();begin
replay:=neuvetra.m78_request(target_company,target_stream,family,'review',request);if replay->'recordId'<>'null'::jsonb then return(replay->>'recordId')::uuid;end if;perform neuvetra.m71_keys(request,'versionId,expectedVersionSha256,expectedDependencySha256,decision,note,acknowledgedLimitations,idempotencyKey');perform neuvetra.m71_keys(r,'id,versionId,versionSha256,dependencies,decision,note,acknowledgedLimitations,reviewerId,reviewedAt,decisionSha256');select h.version_id into head_id from neuvetra.scope1_heads h where h.company_id=target_company and h.id=target_stream and h.family=review_scope1_version.family;select payload,proof into v,p from neuvetra.scope1_versions where company_id=target_company and id=head_id;if v is null or v->'id'is distinct from request->'versionId'or v->'versionSha256'is distinct from request->'expectedVersionSha256'or v#>'{dependencies,dependencySha256}'is distinct from request->'expectedDependencySha256'then raise exception 'review version/dependencies changed'using errcode='23505';end if;
perform neuvetra.m78_assert_current_proof(target_company,p,family='inventory');if v->'dependencies'is distinct from neuvetra.m78_dependencies(p,family)then raise exception 'review dependencies changed'using errcode='23505';end if;if v->'contributorIds'?actor::text then raise exception 'contributor cannot review'using errcode='42501';end if;if exists(select 1 from neuvetra.scope1_reviews where company_id=target_company and version_id=head_id)then raise exception 'review already retained'using errcode='23505';end if;
perform neuvetra.m76_diesel_text(request->'note',2000);if request->'acknowledgedLimitations'is distinct from neuvetra.m78_limitations()or coalesce(request->>'decision','')not in('accepted_bounded_process_screen','accepted_bounded_inventory','changes_requested')or request->>'decision'<>'changes_requested'and(request->>'decision'is distinct from case when family='process_screen'then 'accepted_bounded_process_screen'else 'accepted_bounded_inventory'end or exists(select 1 from jsonb_array_elements(v->'findings')f where f->>'classification'='functional_blocker'))then raise exception 'bounded review acceptance unavailable'using errcode='22023';end if;
captured:=(r->>'reviewedAt')::timestamptz;perform neuvetra.m78_sorted_strings(jsonb_build_array(r->'id'),1,'uuid');if captured<(v->>'createdAt')::timestamptz or captured>clock_timestamp()+interval '2 minutes'or captured<clock_timestamp()-interval '2 minutes'or r->'versionId'is distinct from v->'id'or r->'versionSha256'is distinct from v->'versionSha256'or r->'dependencies'is distinct from v->'dependencies'or r->'reviewerId'is distinct from to_jsonb(actor::text)or r->'decision'is distinct from request->'decision'or r->'note'is distinct from request->'note'or r->'acknowledgedLimitations'is distinct from request->'acknowledgedLimitations'or r->>'decisionSha256'is distinct from neuvetra.m67_hash(jsonb_build_object('companyId',target_company)||(r-'decisionSha256'))then raise exception 'review semantic integrity'using errcode='22023';end if;
insert into neuvetra.scope1_reviews values((r->>'id')::uuid,target_company,head_id,r,r->>'decisionSha256',actor,captured);perform neuvetra.m78_record_request(target_company,target_stream,family,'review',request,(r->>'id')::uuid,r->>'decisionSha256',captured);return(r->>'id')::uuid;end $$;
create function neuvetra.create_scope1_report(target_company uuid,target_stream uuid,family text,request jsonb,r jsonb)returns uuid language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare replay jsonb;v jsonb;p jsonb;review jsonb;s jsonb;snapshot_text text;html text;captured timestamptz;actor uuid:=auth.uid();begin
replay:=neuvetra.m78_request(target_company,target_stream,family,'report',request);if replay->'recordId'<>'null'::jsonb then return(replay->>'recordId')::uuid;end if;if(select count(*)from neuvetra.scope1_reports where company_id=target_company)>=80 then raise exception 'report capacity exceeded'using errcode='54000';end if;perform neuvetra.m71_keys(request,'versionId,expectedVersionSha256,expectedDecisionId,expectedDecisionSha256,expectedReconciliationSha256,idempotencyKey');perform neuvetra.m71_keys(r,'id,companyId,streamId,family,versionId,versionSha256,createdBy,createdAt,rendererVersion,snapshotJson,snapshotSha256,html,htmlSha256,htmlByteLength,reportSha256');select vv.payload,vv.proof into v,p from neuvetra.scope1_versions vv where vv.company_id=target_company and vv.stream_id=target_stream and vv.family=create_scope1_report.family and vv.id=(request->>'versionId')::uuid;if v is null or v->'versionSha256'is distinct from request->'expectedVersionSha256'then raise exception 'report version changed'using errcode='23505';end if;select rr.payload into review from neuvetra.scope1_reviews rr where rr.company_id=target_company and rr.version_id=(v->>'id')::uuid;if request->'expectedDecisionId'is distinct from coalesce(review->'id','null'::jsonb)or request->'expectedDecisionSha256'is distinct from coalesce(review->'decisionSha256','null'::jsonb)or request->'expectedReconciliationSha256'is distinct from coalesce(v#>'{reconciliation,contentSha256}','null'::jsonb)then raise exception 'report review/reconciliation changed'using errcode='23505';end if;
s:=jsonb_build_object('profile','m78-report-snapshot-v1','family',family,'version',v,'review',review,'proof',p,'reconciliation',v->'reconciliation','limitations',neuvetra.m78_limitations());snapshot_text:=neuvetra.m67_canonical(s);html:=neuvetra.m78_render_report(s);captured:=(r->>'createdAt')::timestamptz;perform neuvetra.m78_sorted_strings(jsonb_build_array(r->'id'),1,'uuid');if captured<(v->>'createdAt')::timestamptz or review is not null and captured<(review->>'reviewedAt')::timestamptz or captured>clock_timestamp()+interval '2 minutes'or captured<clock_timestamp()-interval '2 minutes'or r->'companyId'is distinct from to_jsonb(target_company::text)or r->'streamId'is distinct from to_jsonb(target_stream::text)or r->>'family'is distinct from family or r->'versionId'is distinct from v->'id'or r->'versionSha256'is distinct from v->'versionSha256'or r->'createdBy'is distinct from to_jsonb(actor::text)or r->>'rendererVersion'is distinct from 'm78-retained-report-v1'or r->>'snapshotJson'is distinct from snapshot_text or r->>'snapshotSha256'is distinct from encode(sha256(convert_to(snapshot_text,'UTF8')),'hex')or r->>'html'is distinct from html or r->>'htmlSha256'is distinct from encode(sha256(convert_to(html,'UTF8')),'hex')or r->'htmlByteLength'is distinct from to_jsonb(octet_length(html))or r->>'reportSha256'is distinct from neuvetra.m67_hash(r-array['html','snapshotJson','reportSha256'])then raise exception 'report semantic integrity'using errcode='22023';end if;
perform neuvetra.m78_capacity(target_company,octet_length(html)+octet_length(snapshot_text));insert into neuvetra.scope1_reports values((r->>'id')::uuid,target_company,target_stream,family,(v->>'id')::uuid,r,r->>'reportSha256',actor,captured);perform neuvetra.m78_record_request(target_company,target_stream,family,'report',request,(r->>'id')::uuid,r->>'reportSha256',captured);return(r->>'id')::uuid;end $$;

-- Helpers remain private. Runtime can invoke only the lock and three exact writers.
do $$declare f record;begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='neuvetra'and(p.proname like 'm78_%'or p.proname in('save_scope1_version','review_scope1_version','create_scope1_report'))loop execute format('revoke all on function %s from public,authenticated,neuvetra_runtime',f.signature);end loop;end $$;
grant execute on function neuvetra.m78_lock(uuid,boolean),neuvetra.save_scope1_version(uuid,uuid,text,jsonb,jsonb,jsonb),neuvetra.review_scope1_version(uuid,uuid,text,jsonb,jsonb),neuvetra.create_scope1_report(uuid,uuid,text,jsonb,jsonb)to neuvetra_runtime;

create function neuvetra.m78_policy()returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select '{"id":"m78-scope1-compatible-candidate-v1","status":"accounting_reviewed_candidate","releaseEligible":false,"reviewArtifact":{"path":"evaluations/research-qa/m78-accounting-review.md","sha256":"5d5b04d73266e4954ccd9cdc29595a2ed9c6446e255de9fd987a2e2a262dc69c"},"methods":[{"family":"natural_gas","methodSha256":"a596ea0d377f33ac34e1333852c313c855c2a18ac08006525a78bbfb7cce9898"},{"family":"mobile_diesel","methodSha256":"7598384902729e8a6708beb359e7564f500ad85c0d3ad38f094ee580a05c0497"},{"family":"stationary_diesel","methodSha256":"8924b6c99a7b2b1525f2f2ef641978bbdfc5c7116c40a9fc828e418e56a4a722"},{"family":"fugitive","methodSha256":"acbfed90deaf7c164fe889b87732a998396ace265c92973ba3f79c6a71c038af"}],"gasGwps":[{"gas":"CO2","gwp":"1","gasKind":"single_gas"},{"gas":"CH4","gwp":"28","gasKind":"single_gas"},{"gas":"N2O","gwp":"265","gasKind":"single_gas"},{"gas":"HFC-134a","gwp":"1300","gasKind":"single_gas"},{"gas":"HFC-227ea","gwp":"3350","gasKind":"single_gas"},{"gas":"R-410A","gwp":"1924","gasKind":"blend"}],"blendDisclosure":"opaque_blend_no_constituent_guess","rounding":"half_even_4dp","policySha256":"83588037114ca6e688a221a4027dab1e480ad898aa29d2bcbeaec24ad9dcb303"}'::jsonb$$;

revoke all on function neuvetra.m78_policy()from public,authenticated,neuvetra_runtime;

create function neuvetra.m78_source_label(c jsonb,id text)returns text language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select neuvetra.m75_html_escape(coalesce(src->>'name',id))||' · '||neuvetra.m75_html_escape((select e->>'legalName'from jsonb_array_elements(c->'entities')e where e->'id'=src->'entityId'limit 1))||' · '||neuvetra.m75_html_escape(coalesce((select f->>'name'from jsonb_array_elements(c->'facilities')f where f->'id'=src->'facilityId'limit 1),'Controlled non-facility activity'))||' · '||neuvetra.m75_html_escape(id)from(select(select x from jsonb_array_elements(c->'sources')x where x->>'id'=id limit 1)src)q$$;
create function neuvetra.m78_statement_links(refs jsonb,statements jsonb)returns text language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select coalesce(string_agg(case when e is null then neuvetra.m75_html_escape(ref)else '<a href="#statement-'||neuvetra.m75_html_escape(e->>'id')||'">'||neuvetra.m75_html_escape(ref)||'</a>'end,'<br>'order by n),'')from jsonb_array_elements_text(refs)with ordinality q(ref,n)left join lateral(select e from jsonb_array_elements(statements)e where e->>'reference'=ref limit 1)r on true$$;
create function neuvetra.m78_report_detail_sections(s jsonb)returns text language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare c jsonb:=s#>'{proof,coverageVersion,snapshot}';v jsonb; a jsonb;statements jsonb;discovery text;basis text;states jsonb:='{"unknown":"Unknown — unresolved","indicated":"Indicated source — unsupported","not_applicable_proposed":"Proposed not applicable — inspection and separate review required","covered_by_sources":"Covered by exact named physical sources"}';categories jsonb:='{"mineral_products":"Mineral products","chemical_production":"Chemical production","metal_production":"Metal production","oil_and_gas":"Oil and gas","waste_treatment":"Waste treatment","agricultural_biological":"Agricultural and biological activity","other_direct_process":"Other direct process emissions"}';begin
v:=case when s->>'family'='process_screen'then s->'version'else s#>'{proof,process,version}'end;a:=case when v#>>'{activity,profile}'='synthetic-process-screen-v1'then v->'activity'else null end;statements:=coalesce(v->'statements','[]'::jsonb);
if a is not null then discovery:='<h2>Seven-gas applicability and process discovery</h2><p>These are retained fictional applicability decisions, not zero-emission gas calculations. Each decision covers the retained inspected locations and controlled off-site operations.</p><table><thead><tr><th>Gas group</th><th>Disposition and scope</th><th>Retained evidence</th></tr></thead><tbody>'||coalesce((select string_agg('<tr><td data-label="Gas group">'||neuvetra.m75_html_escape(g->>'gasGroup')||'</td><td data-label="Disposition and scope">'||neuvetra.m75_html_escape(states->>(g->>'state'))||'<br>'||neuvetra.m75_html_escape(g->>'reason')||'<br>'||coalesce((select string_agg(neuvetra.m78_source_label(c,id),'<br>'order by n)from jsonb_array_elements_text(g->'sourceIds')with ordinality q(id,n)),'')||coalesce((select string_agg(neuvetra.m75_html_escape(id),'<br>'order by n)from jsonb_array_elements_text(g->'discoveredSourceIds')with ordinality q(id,n)),'')||'</td><td data-label="Retained evidence">'||neuvetra.m78_statement_links(g->'evidenceReferences',statements)||'</td></tr>',''order by n)from jsonb_array_elements(a->'gasCoverage')with ordinality q(g,n)),'')||'</tbody></table><h3>Process categories</h3><table><thead><tr><th>Category</th><th>Disposition and rationale</th><th>Retained evidence</th></tr></thead><tbody>'||coalesce((select string_agg('<tr><td data-label="Category">'||neuvetra.m75_html_escape(categories->>(x->>'category'))||'</td><td data-label="Disposition and rationale">'||neuvetra.m75_html_escape(states->>(x->>'disposition'))||'<br>'||neuvetra.m75_html_escape(x->>'reason')||case when x->'discoveredSourceId'<>'null'::jsonb then '<br>Discovered source '||neuvetra.m75_html_escape(x->>'discoveredSourceId')else ''end||'</td><td data-label="Retained evidence">'||neuvetra.m78_statement_links(x->'evidenceReferences',statements)||'</td></tr>',''order by n)from jsonb_array_elements(a->'assessments')with ordinality q(x,n)),'')||'</tbody></table>';else discovery:='<h2>Process discovery</h2><p>No retained process discovery is available; applicability remains unresolved.</p>';end if;
select coalesce(string_agg('<li>'||neuvetra.m78_source_label(c,x#>>'{version,activity,binding,sourceId}')||'<br>'||neuvetra.m75_html_escape(case x->>'family'when 'fugitive'then 'Servicing gas consumption estimate; linked prior releases are included once in the refill, not added again. Declared service evidence is not independently verified.'when 'stationary_diesel'then 'Stationary diesel estimate uses default higher heating value, not measured customer fuel heat content.'when 'mobile_diesel'then 'Mobile fossil-diesel candidate calculation uses dedicated annual consumption and vehicle distance.'else 'Natural-gas candidate calculation uses dedicated annual heat-input consumption.'end)||'<br>Retained source version '||neuvetra.m75_html_escape(x#>>'{version,id}')||'</li>',''order by n),'')into basis from jsonb_array_elements(s#>'{proof,sourceVersions}')with ordinality q(x,n);return discovery||'<h2>Source method and estimate basis</h2><ul>'||basis||'</ul>';end $$;
revoke all on function neuvetra.m78_source_label(jsonb,text),neuvetra.m78_statement_links(jsonb,jsonb),neuvetra.m78_report_detail_sections(jsonb)from public,authenticated,neuvetra_runtime;
